package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

public class OnlineStockSpanTest {

    @Test
    public void next_PriceZero_ReturnOne() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertEquals(1, solution.next(0));
    }

    @Test
    public void next_PricePositive_ReturnOne() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertEquals(1, solution.next(10));
    }

    @Test
    public void next_PriceNegative_ReturnOne() {
        OnlineStockSpan solution = new OnlineStockSpan();
        assertEquals(1, solution.next(-5));
    }

    @Test
    public void calculateSpans_EmptyArray_ReturnEmptyArray() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[0]);
        assert result.length == 0;
    }

    @Test
    public void calculateSpans_SingleElementArray_ReturnArrayWithOneElement() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[]{10});
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_ReturnCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[]{100, 80, 75, 70});
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
        assertEquals(4, result[3]);
    }

    @Test
    public void next_SamePriceTwice_ReturnTwo() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] previousPrices = {10};
        int[] currentPrices = {10};
        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        for (int i = 1; i <= 2; i++) {
            solution.next(currentPrices[i-1]);
            int nextPrice = solution.next(currentPrices[i-1]);
            if (currentPrices[i-1] == previousPrices[i-1]) {
                assert stack.peek() == nextPrice;
            } else {
                while (!stack.isEmpty()) {
                    stack.pop();
                }
                stack.push(nextPrice);
            }
            previousPrices[i] = currentPrices[i];
        }
        assertEquals(2, solution.next(currentPrices[2]));
    }

    @Test
    public void calculateSpans_MultipleElementsArray_ReturnCorrectSpans() {
        OnlineStockSpan solution = new OnlineStockSpan();
        int[] result = solution.calculateSpans(new int[]{100, 80, 75, 70});
        assertEquals(1, result[0]);
        assertEquals(2, result[1]);
        assertEquals(3, result[2]);
        assertEquals(4, result[3]);
    }

}

